interface XmlNode {
  name: string;
  attributes: Array<[string, string]>;
  children: XmlNode[];
  text: string;
}

const repeatedPaths = new Set([
  "no_ar/historico_recente/musica",
  "roteiro/participantes/participante",
  "roteiro/escalada/item",
  "roteiro/blocos/bloco",
  "roteiro/blocos/bloco/noticia",
  "roteiro/podcast/perguntas/pergunta",
  "roteiro/podcast/imagens_apoio/imagem",
  "roteiro/podcast/videos_apoio/video",
]);
const groupingNodes = new Set(["no_ar", "interatividade"]);

/**
 * Accepts the XML generated by serve-xml-geral, whose values are already escaped.
 */
export function flattenGeralXml(xml: string): string {
  const document: XmlNode = { name: "", attributes: [], children: [], text: "" };
  const stack = [document];
  const tokens = xml.match(/<(?:"[^"]*"|'[^']*'|[^'">])*>|[^<]+/g) || [];
  for (const token of tokens) {
    if (token.startsWith("<?xml")) continue;
    if (token.startsWith("</")) {
      const name = token.slice(2, -1).trim();
      if (stack.length < 2 || stack[stack.length - 1].name !== name) throw new Error("XML geral com fechamento inválido");
      stack.pop();
    } else if (token.startsWith("<")) {
      const match = /^<([a-zA-Z_][\w.-]*)((?:\s+[a-zA-Z_][\w.-]*="[^"]*")*)\s*(\/?)>$/.exec(token);
      if (!match) throw new Error("XML geral com elemento inválido");
      const attributes: Array<[string, string]> = [];
      for (const attribute of match[2].matchAll(/\s+([a-zA-Z_][\w.-]*)="([^"]*)"/g)) attributes.push([attribute[1], attribute[2]]);
      const node: XmlNode = { name: match[1], attributes, children: [], text: "" };
      stack[stack.length - 1].children.push(node);
      if (!match[3]) stack.push(node);
    } else {
      stack[stack.length - 1].text += token;
    }
  }
  if (stack.length !== 1 || document.children.length !== 1 || document.children[0].name !== "geral") {
    throw new Error("XML geral inválido");
  }

  const fields: string[] = [];
  const names = new Set<string>();
  const add = (name: string, value: string) => {
    if (names.has(name)) throw new Error(`Campo duplicado no XML geral: ${name}`);
    names.add(name);
    fields.push(`  <${name}>${value}</${name}>`);
  };
  const visit = (node: XmlNode, path: string[], namesPath: string[], index: number) => {
    const rawPath = [...path, node.name];
    const rawPathName = rawPath.join("/");
    const parts = groupingNodes.has(rawPathName)
      ? namesPath
      : [...namesPath, rawPathName === "no_ar/historico_recente" ? "historico" : node.name];
    if (repeatedPaths.has(rawPath.join("/"))) parts.push(String(index));
    for (const [name, value] of node.attributes) add([...parts, name].join("_"), value);
    if (node.children.length === 0) {
      if (parts.length === 0 && !node.text.trim()) return;
      add(parts.join("_"), node.text);
      return;
    }
    if (node.text.trim()) throw new Error(`Conteúdo misto no XML geral: ${rawPath.join("/")}`);
    const counts = new Map<string, number>();
    for (const child of node.children) {
      const next = (counts.get(child.name) || 0) + 1;
      counts.set(child.name, next);
      visit(child, rawPath, parts, next);
    }
  };
  for (const attribute of document.children[0].attributes) add(attribute[0], attribute[1]);
  const counts = new Map<string, number>();
  for (const child of document.children[0].children) {
    const next = (counts.get(child.name) || 0) + 1;
    counts.set(child.name, next);
    visit(child, [], [], next);
  }
  return `<?xml version="1.0" encoding="UTF-8"?>\n<geral>\n${fields.join("\n")}\n</geral>`;
}
